insert into pages (title, slug, kind, content, visibility) values ('Analytics engineering', 'analytics-engineering', 'wiki', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Analytics engineering is the discipline this whole wiki is about. It's the practice of turning raw data into clean, tested, documented, version-controlled datasets that people and, increasingly, machines can trust. This section is the umbrella: it defines the discipline and ties together everything else here."}]},{"type":"paragraph","content":[{"type":"text","text":"Everything in taro is an instance of it. "},{"type":"wikilink","attrs":{"title":"Data modeling"}},{"type":"text","text":" is the meaning work. "},{"type":"wikilink","attrs":{"title":"Product analytics"}},{"type":"text","text":", "},{"type":"wikilink","attrs":{"title":"Marketing analytics"}},{"type":"text","text":", "},{"type":"wikilink","attrs":{"title":"Sales analytics"}},{"type":"text","text":", "},{"type":"wikilink","attrs":{"title":"Customer experience analytics"}},{"type":"text","text":", "},{"type":"wikilink","attrs":{"title":"Finance analytics"}},{"type":"text","text":", and "},{"type":"wikilink","attrs":{"title":"Operations analytics"}},{"type":"text","text":" are the domains it serves. "},{"type":"wikilink","attrs":{"title":"Transformation and orchestration"}},{"type":"text","text":" is how the work gets built and run. This section is the why behind all of them."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Theory"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The discipline — ","marks":[{"type":"bold"}]},{"type":"text","text":"what analytics engineering is, the role, and its principles."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The stack — ","marks":[{"type":"bold"}]},{"type":"text","text":"the modern data stack, the semantic layer, and data contracts."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The end state — ","marks":[{"type":"bold"}]},{"type":"text","text":"serving governed data to AI agents and presentation layers, and what AI does to the role."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The 2026 throughline, and taro's whole thesis: the deliverable is shifting from dashboards to governed, machine-readable context. Define meaning once, model it for humans and machines, and let everything read from it. See "},{"type":"wikilink","attrs":{"title":"Serving data to AI agents"}},{"type":"text","text":" for where that lands."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"What analytics engineering is"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Serving data to AI agents"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Analytics engineering voices and canon"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('What analytics engineering is', 'what-analytics-engineering-is', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Analytics engineering is software engineering applied to analytics data. The analytics engineer owns the transformation layer, the T in ELT, and the modeling and semantics that turn raw tables into the analytics-ready datasets analysts and business users actually use."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Where it came from"}]},{"type":"paragraph","content":[{"type":"text","text":"The role emerged around 2018 and 2019 out of the Locally Optimistic community and dbt Labs. Tristan Handy is the name most associated with it; Michael Kaminsky's writing gave it its first formal name. It was made possible by the modern data stack: cloud warehouses plus ELT plus dbt created room for a person with an analyst's domain knowledge and an engineer's rigor."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The neighbors"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Data engineer — ","marks":[{"type":"bold"}]},{"type":"text","text":"builds and operates ingestion and infrastructure, the E and L and the platform. Lower-level, systems-focused."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Data analyst — ","marks":[{"type":"bold"}]},{"type":"text","text":"consumes modeled data to answer questions and build dashboards. Closer to the business."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Analytics engineer — ","marks":[{"type":"bold"}]},{"type":"text","text":"owns the layer in between, applying engineering discipline to the data analysts depend on."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The mission is simple to state and hard to do: build trust in data. Everything else in this section is in service of that. See "},{"type":"wikilink","attrs":{"title":"Principles of analytics engineering"}},{"type":"text","text":" for how."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"The analytics engineer's role"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Principles of analytics engineering"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Transformation and orchestration"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('The analytics engineer''s role', 'the-analytics-engineer-role', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In practice the analytics engineer is the person who makes sure the number is right and means the same thing everywhere. The day-to-day is modeling data in dbt, defining and testing metrics, documenting them, and owning the datasets downstream teams build on."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"What the role owns"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The transformation layer — ","marks":[{"type":"bold"}]},{"type":"text","text":"the staging-to-marts models that turn raw data into business-conformed tables."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Definitions and semantics — ","marks":[{"type":"bold"}]},{"type":"text","text":"what \"customer\" and \"active\" and \"revenue\" mean, encoded once so they can't drift."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Trust and quality — ","marks":[{"type":"bold"}]},{"type":"text","text":"the tests, contracts, and documentation that let people rely on the output."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The role sits at a busy intersection, which is also its main failure mode: when ownership is ambiguous, nobody owns the definitions and they fragment. dbt's 2026 survey still names ambiguous data ownership as a top obstacle. The fix is organizational as much as technical, the same hub-and-spoke argument made in "},{"type":"wikilink","attrs":{"title":"Org models (hub and spoke)"}},{"type":"text","text":" and "},{"type":"wikilink","attrs":{"title":"Team and ownership models"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"What analytics engineering is"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Principles of analytics engineering"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Org models (hub and spoke)"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Principles of analytics engineering', 'principles-of-analytics-engineering', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The defining move of the discipline is borrowing the practices that made software reliable and pointing them at analytics."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Version control — ","marks":[{"type":"bold"}]},{"type":"text","text":"transformation logic lives in git, reviewed in pull requests, not buried in a BI tool."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Testing — ","marks":[{"type":"bold"}]},{"type":"text","text":"data tests and unit tests assert the things that would make a number wrong, run automatically."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CI/CD — ","marks":[{"type":"bold"}]},{"type":"text","text":"changes build and test before they reach production, covered in "}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Modularity and DRY — ","marks":[{"type":"bold"}]},{"type":"text","text":"define a piece of logic once and reference it, rather than copying it across queries."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Documentation and lineage — ","marks":[{"type":"bold"}]},{"type":"text","text":"docs and a dependency graph are first-class artifacts, not afterthoughts."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Three commitments on top"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Data as a product — ","marks":[{"type":"bold"}]},{"type":"text","text":"modeled datasets are owned, maintained products with consumers, not one-off queries."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Transformations as code — ","marks":[{"type":"bold"}]},{"type":"text","text":"business logic is version-controlled code, not clicks in a dashboard."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Build trust — ","marks":[{"type":"bold"}]},{"type":"text","text":"the entire point is reliable, consistent, defensible numbers."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The 2026 signal worth internalizing, straight from dbt's own report: AI has made building faster, but trust and governance haven't kept up, and trust is now the top priority. The differentiator is discipline, and governance has to be infrastructure rather than an afterthought. That gap is exactly the human work that survives, see "},{"type":"wikilink","attrs":{"title":"AI and the future of analytics engineering"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"CI/CD and DataOps"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Data contracts and trust"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"AI and the future of analytics engineering"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('The modern data stack', 'the-modern-data-stack', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The modern data stack is the set of cloud tools analytics engineering runs on: ingestion (Fivetran, Airbyte) into a warehouse or lakehouse (Snowflake, BigQuery, Databricks), transformation (dbt), then BI and activation on top. Its arrival is what made the discipline possible."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"How it evolved"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"2020, assembly — ","marks":[{"type":"bold"}]},{"type":"text","text":"buy a best-of-breed tool for every layer and wire them together. Powerful, and quickly sprawling."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"2023 to 2026, consolidation — ","marks":[{"type":"bold"}]},{"type":"text","text":"a backlash against cost and complexity. The 2026 stack is leaner, three or four well-chosen tools rather than nine, with vendor mergers (Fivetran and dbt Labs) reshaping the map."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The lakehouse — ","marks":[{"type":"bold"}]},{"type":"text","text":"object storage plus open table formats (Iceberg, Delta) blurring the warehouse and data lake into one substrate."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The sharp critique to keep in mind is that some of this consolidation is unification in name only, bundled acquisitions that create lock-in rather than real interoperability. The genuinely unifying layer is not storage, it's meaning, which is why the center of gravity has moved to "},{"type":"wikilink","attrs":{"title":"The semantic layer"}},{"type":"text","text":". taro's own position is that coherence comes from shared definitions, not a single vendor."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"The semantic layer"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"The dbt ecosystem in 2026"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"What analytics engineering is"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('The semantic layer', 'the-semantic-layer', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The semantic layer is where a metric is defined once and served everywhere. Revenue, active customer, MRR, computed from one governed definition that every dashboard, notebook, and agent reads, so the numbers can't diverge. It's the same idea as "},{"type":"wikilink","attrs":{"title":"Semantics & the semantic layer"}},{"type":"text","text":" in data modeling, here as the architectural centerpiece of the whole stack."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"How it works"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Headless BI — ","marks":[{"type":"bold"}]},{"type":"text","text":"metric definitions are decoupled from any one visualization tool and served by API or SQL. The logic leaves the BI layer and moves into code."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The tools — ","marks":[{"type":"bold"}]},{"type":"text","text":"the dbt Semantic Layer with MetricFlow, plus Cube, AtScale, and Malloy; warehouse-native variants from Snowflake and Databricks."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The contract — ","marks":[{"type":"bold"}]},{"type":"text","text":"it's the enforcement point for governance, access policies, certified definitions, and lineage, before any query runs."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The 2026 milestone is the Open Semantic Interchange, a vendor-neutral standard for exchanging semantic models, with a v1.0 spec released in January 2026 backed by Snowflake, dbt Labs, Databricks, and others. The bet is that the semantic layer becomes the shared contract between modeled data and every consumer, including AI. That bet is the subject of "},{"type":"wikilink","attrs":{"title":"Serving data to AI agents"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Semantics & the semantic layer"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Serving data to AI agents"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"The modern data stack"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Data contracts and trust', 'data-contracts-and-trust', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A data contract is an explicit, enforced agreement about the shape and meaning of data a producer hands to a consumer: the columns, the types, the semantics, the guarantees. It's how you stop silent upstream changes from quietly breaking everything downstream."}]},{"type":"paragraph","content":[{"type":"text","text":"The idea matters more as data feeds more than dashboards. Chad Sanderson, the loudest voice here, frames data contracts in 2026 as data quality for AI: when agents consume your data, the contract is what lets them, and other systems, reason about change safely. dbt's model contracts are one concrete implementation, declaring a model's output shape so it fails to build if it drifts."}]},{"type":"paragraph","content":[{"type":"text","text":"Contracts are the producer-side complement to "},{"type":"wikilink","attrs":{"title":"Testing & data quality"}},{"type":"text","text":" on the consumer side, and together they're how the discipline delivers on its core promise. Trust isn't a vibe, it's a set of enforced agreements plus tests plus observability, owned by someone. Without it, the AI end state in "},{"type":"wikilink","attrs":{"title":"Serving data to AI agents"}},{"type":"text","text":" is just confident, wrong answers at scale."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Testing & data quality"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Principles of analytics engineering"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Serving data to AI agents"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Serving data to AI agents', 'serving-data-to-ai-agents', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"This is the end state the discipline is heading toward, and taro's reason for existing. The deliverable of analytics engineering is increasingly not a dashboard but governed, machine-readable context that an AI agent can consume and trust."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Why text-to-SQL alone fails"}]},{"type":"paragraph","content":[{"type":"text","text":"Letting an LLM write SQL straight against raw tables has gotten impressively accurate, but it fails in the worst way: silently. It returns a plausible, wrong answer, because the model can't derive business meaning from cryptic schemas, so it guesses joins, grain, and semantics. The failure is in what it queries, not how."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Why the semantic layer fixes it"}]},{"type":"paragraph","content":[{"type":"text","text":"Route the same question through a governed "},{"type":"wikilink","attrs":{"title":"The semantic layer"}},{"type":"text","text":" and generation becomes deterministic against codified metrics and dimensions, so the agent can't invent a bad join or aggregation. The 2026 pattern is semantic layer first, text-to-SQL as a fallback for exploration. Governance is enforced at the moment meaning is resolved, before any SQL exists."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"How agents get the context"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"MCP — ","marks":[{"type":"bold"}]},{"type":"text","text":"the Model Context Protocol is how agents discover and call external context. The dbt MCP server exposes a project's models, metrics, docs, lineage, and tests as tools an agent can use."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Warehouse-native assistants — ","marks":[{"type":"bold"}]},{"type":"text","text":"Snowflake Cortex Analyst, Databricks Genie, and BigQuery Gemini all read a semantic model to answer natural-language questions, and are correspondingly locked to their platform."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The thesis in one line: an agent is only as trustworthy as the semantics it reads, so the analytics engineer's job becomes building the context layer agents depend on. That is what taro is, see "},{"type":"wikilink","attrs":{"title":"How taro is built on these ideas"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"The semantic layer"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Presentation layers"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"How taro is built on these ideas"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Presentation layers', 'presentation-layers', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The presentation layer is wherever a human (or now an agent) actually consumes the data. The point of 2026 is that there isn't one anymore, there are many, and they should all read from the same governed definitions so the number is consistent regardless of surface."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dashboards and BI — ","marks":[{"type":"bold"}]},{"type":"text","text":"the classic surface, Looker, Tableau, Power BI. Still central, no longer the only thing."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Embedded analytics and data apps — ","marks":[{"type":"bold"}]},{"type":"text","text":"analytics surfaced inside other products, fed by the same semantic layer."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Notebooks — ","marks":[{"type":"bold"}]},{"type":"text","text":"for exploratory and technical consumers."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Chat and agent interfaces — ","marks":[{"type":"bold"}]},{"type":"text","text":"the fastest-growing surface, where a question gets a governed answer rather than a chart."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The unifying principle is that the presentation layer should be thin and the meaning should live upstream. When every surface reads from one "},{"type":"wikilink","attrs":{"title":"The semantic layer"}},{"type":"text","text":", a dashboard, an embedded chart, and an agent all return the same revenue number. When they each recompute it, you get the drift the whole discipline exists to prevent. taro itself is a presentation layer over a knowledge graph, which is the point of "},{"type":"wikilink","attrs":{"title":"How taro is built on these ideas"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Serving data to AI agents"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"The semantic layer"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"How taro is built on these ideas"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('AI and the future of analytics engineering', 'ai-and-the-future-of-analytics-engineering', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The honest version, without the hype: AI is changing the analytics engineer's job, not ending it. The work is moving up the stack, from writing SQL to curating the context that makes AI output reliable."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"What AI takes"}]},{"type":"paragraph","content":[{"type":"text","text":"Routine modeling, boilerplate SQL, first-draft documentation, and a lot of the mechanical translation. dbt's 2026 survey has 72% of teams prioritizing AI-assisted coding. That part of the job is genuinely getting automated."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"What stays human"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Semantics and context — ","marks":[{"type":"bold"}]},{"type":"text","text":"encoding what data means, the grain, the edge cases. An LLM can't infer your business from a schema."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Trust and governance — ","marks":[{"type":"bold"}]},{"type":"text","text":"certifying definitions, owning quality, deciding what's safe to expose to an agent."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Judgment — ","marks":[{"type":"bold"}]},{"type":"text","text":"asking the right question and interpreting the answer in context."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The clearest signal is the gap in dbt's own data: AI-assisted coding is at 72% but AI-assisted pipeline management at only 24%, and 71% worry about bad outputs reaching stakeholders. AI acceleration is outrunning trust and governance, and closing that gap is precisely the human-owned work that remains. The role becomes less about producing SQL and more about being the person who can be trusted to say what the data means. That is the bet behind "},{"type":"wikilink","attrs":{"title":"Serving data to AI agents"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Principles of analytics engineering"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Serving data to AI agents"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Data contracts and trust"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('How taro is built on these ideas', 'how-taro-is-built-on-these-ideas', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"taro is an argument made in software. Every section of this wiki is the same idea seen from a different angle: define meaning once, model it for humans and machines, and let everything read from it. This page ties the threads together."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The thesis across the wiki"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Meaning first — ","marks":[{"type":"bold"}]},{"type":"text","text":"the semantic layer recurs everywhere, the finance metrics, the product metrics, the marketing definitions, the operational KPIs, all argue for one governed definition. See "}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Grain everywhere — ","marks":[{"type":"bold"}]},{"type":"text","text":"from the MRR waterfall to support tickets to cost lines, the same "}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"One graph — ","marks":[{"type":"bold"}]},{"type":"text","text":"wiki pages, concepts, catalog models, and the domain sections are nodes in a single linked knowledge graph, which is exactly the machine-readable context an agent needs."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"taro is itself a presentation layer over that graph, and it exposes a machine-readable context bundle so an agent can read the whole thing. That is the end state from "},{"type":"wikilink","attrs":{"title":"Serving data to AI agents"}},{"type":"text","text":" made concrete: the knowledge platform is the context layer. The domains, "},{"type":"wikilink","attrs":{"title":"Marketing analytics"}},{"type":"text","text":" through "},{"type":"wikilink","attrs":{"title":"Operations analytics"}},{"type":"text","text":", are the breadth; "},{"type":"wikilink","attrs":{"title":"Data modeling"}},{"type":"text","text":" and "},{"type":"wikilink","attrs":{"title":"Transformation and orchestration"}},{"type":"text","text":" are the depth; this section is the why."}]},{"type":"paragraph","content":[{"type":"text","text":"If there's one thing to take from the whole wiki: coherence over collection. A pile of dashboards and definitions that disagree is worth less than a smaller, coherent, governed set that everything, and everyone, can trust."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Serving data to AI agents"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Semantics & the semantic layer"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Data modeling"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Analytics engineering voices and canon', 'analytics-engineering-voices', 'wiki', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The discipline has a real and active canon. Who to read and why, weighted toward the people still shaping it in 2026."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The founders and definers"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tristan Handy — ","marks":[{"type":"bold"}]},{"type":"text","text":"dbt Labs, coined \"analytics engineer\"; the Analytics Engineering Roundup newsletter and the \"year of context\" framing."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Claire Carroll — ","marks":[{"type":"bold"}]},{"type":"text","text":"early dbt community voice who helped codify the role and its practice."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Michael Kaminsky and Locally Optimistic — ","marks":[{"type":"bold"}]},{"type":"text","text":"the community where the role was named."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The sharpest current thinkers"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Benn Stancil — ","marks":[{"type":"bold"}]},{"type":"text","text":"the best essays on the semantic and context layers and the pivot to agents; also the most reliable hype-corrective."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Chad Sanderson — ","marks":[{"type":"bold"}]},{"type":"text","text":"data contracts and data-as-a-product; his book on data contracts lands in 2026."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Joe Reis and Matt Housley — ","marks":[{"type":"bold"}]},{"type":"text","text":"Fundamentals of Data Engineering, the canon for the broader lifecycle this discipline sits inside."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Where it happens"}]},{"type":"paragraph","content":[{"type":"text","text":"The dbt community and Coalesce, Locally Optimistic, and the vendor blogs (dbt Labs, Snowflake, Databricks) that, for better or worse, drive much of the 2026 discourse on agents and the semantic layer."}]},{"type":"paragraph","content":[{"type":"text","text":"The AI-and-agents material moves monthly. Treat specific tool and benchmark claims as as-of-2026 and check them before quoting.","marks":[{"type":"italic"}]}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
