-- Analytics engineering wiki section (top-level sibling of "Data modeling").
-- Idempotent: pages upsert by slug; parent wiring is join-based and safe to re-run.
-- Wikilinks are wired by the combined seed_ae_crosslinks.sql pass (run after both
-- new sections + the five domain seeds exist). Mirrors what was seeded via the
-- Supabase MCP (2026-06), replacing the removed "Analytics engineering practice".

update pages c set parent_id = pa.id from pages pa where pa.slug = 'analytics-engineering' and c.slug in ('what-analytics-engineering-is','the-analytics-engineer-role','principles-of-analytics-engineering','the-modern-data-stack','the-semantic-layer','data-contracts-and-trust','serving-data-to-ai-agents','presentation-layers','ai-and-the-future-of-analytics-engineering','how-taro-is-built-on-these-ideas','analytics-engineering-voices');
